sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    g_form.hideFieldMsg('estimated_cost', true);

    if (isLoading || !newValue) return;

    var standardRates = {
        general_service: 2500,
        oil_change: 1200,
        inspection: 800
    };

    if (standardRates[newValue]) {
        g_form.setValue('estimated_cost', standardRates[newValue]);
    } else {
        g_form.clearValue('estimated_cost');
        g_form.showFieldMsg(
            'estimated_cost',
            'Repair cost will be estimated after inspection.',
            'info'
        );
    }
}
